import * as T from 'three';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
import {closest} from './driving-physics.js';
import {drapeGeometry as drape} from './drape-geometry.js';
let meta=null,values=null,profiles={},waterLevels={},segments=new Map();
export function configureTerrain(m,v,p={}){meta=m;values=v;profiles=p;segments=new Map();for(const [id,profile] of Object.entries(p)){for(let i=1;i<profile.points.length;i++){const a=profile.points[i-1],b=profile.points[i],r=profile.width/2+1;const s={a,b,id,width:profile.width,bridge:profile.bridge};for(let x=Math.floor((Math.min(a[0],b[0])-r)/50);x<=Math.floor((Math.max(a[0],b[0])+r)/50);x++)for(let z=Math.floor((Math.min(a[1],b[1])-r)/50);z<=Math.floor((Math.max(a[1],b[1])+r)/50);z++){const k=x+','+z;if(!segments.has(k))segments.set(k,[]);segments.get(k).push(s);}}}}
export function heightAt(x,z){if(!meta)return 0;const u=Math.max(0,Math.min(meta.nx-1.000001,(x-meta.xmin)/meta.step)),v=Math.max(0,Math.min(meta.nz-1.000001,(z-meta.zmin)/meta.step)),i=Math.floor(u),j=Math.floor(v),a=u-i,b=v-j,k=j*meta.nx+i;return (values[k]*(1-a)+values[k+1]*a)*(1-b)+(values[k+meta.nx]*(1-a)+values[k+meta.nx+1]*a)*b;}
function segmentSample(x,z,s){const p=closest(x,z,s.a,s.b),length=Math.hypot(s.b[0]-s.a[0],s.b[1]-s.a[1]),t=length?Math.hypot(p.x-s.a[0],p.z-s.a[1])/length:0;return {...p,y:s.a[2]+(s.b[2]-s.a[2])*t,s};}
export function roadHeight(x,z,id){const list=segments.get(Math.floor(x/50)+','+Math.floor(z/50))||[];let best;for(const s of list)if(s.id===String(id)){const p=segmentSample(x,z,s);if(!best||p.d<best.d)best=p;}return best&&best.d<=best.s.width/2+4?best.y:heightAt(x,z);}
export function driveHeight(x,z,reference=heightAt(x,z)){const ground=heightAt(x,z);let best=ground,score=Math.abs(ground-reference);for(const s of segments.get(Math.floor(x/50)+','+Math.floor(z/50))||[]){if(!/^(motorway|trunk|primary|secondary|tertiary|residential|unclassified|living_street|service|.*_link)$/.test(profiles[s.id].highway))continue;const p=segmentSample(x,z,s);if(p.d>Math.max(.15,s.width/2-1.0))continue;const d=Math.abs(p.y-reference);if(d<score+.16){best=p.y;score=d;}}return best;}
export function waterHeight(id,poly){return waterLevels[id]??heightAt(...poly.outer[0]);}
export function isElevated(id){return !!profiles[id];}
export function buildingBase(poly){return Math.max(...poly.outer.map(p=>heightAt(...p)));}
export function drapeGeometry(g,sample=heightAt,maxEdge=55){return drape(g,sample,maxEdge);}
export async function loadTerrain(scene){const [m,v,p,w]=await Promise.all([fetch('./data/terrain.json').then(r=>r.json()),fetch('./data/terrain.bin').then(r=>r.arrayBuffer()),fetch('./data/bridges.json').then(r=>r.json()),fetch('./data/water-levels.json').then(r=>r.json())]);waterLevels=w;configureTerrain(m,new Float32Array(v),p.profiles);const material=new T.MeshStandardMaterial({color:'#385448',roughness:1});
 // Independent 1.28 km patches retain the full DEM but can be frustum culled.
 for(let z0=0;z0<m.nz-1;z0+=32)for(let x0=0;x0<m.nx-1;x0+=32){
 const nx=Math.min(33,m.nx-x0),nz=Math.min(33,m.nz-z0),pos=new Float32Array(nx*nz*3),normals=new Float32Array(nx*nz*3),idx=[];
 for(let z=0;z<nz;z++)for(let x=0;x<nx;x++){const X=x+x0,Z=z+z0,k=z*nx+x,global=Z*m.nx+X;pos[k*3]=m.xmin+X*m.step;pos[k*3+1]=values[global]-.18;pos[k*3+2]=m.zmin+Z*m.step;
 const left=Math.max(0,X-1),right=Math.min(m.nx-1,X+1),up=Math.max(0,Z-1),down=Math.min(m.nz-1,Z+1);const dx=(values[Z*m.nx+right]-values[Z*m.nx+left])/((right-left)*m.step),dz=(values[down*m.nx+X]-values[up*m.nx+X])/((down-up)*m.step),n=Math.hypot(dx,1,dz);normals.set([-dx/n,1/n,-dz/n],k*3);
 if(x<nx-1&&z<nz-1)idx.push(k,k+nx,k+1,k+1,k+nx,k+nx+1);}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(pos,3));g.setAttribute('normal',new T.BufferAttribute(normals,3));g.setIndex(idx);g.computeBoundingSphere();scene.add(new T.Mesh(g,material));}
 return {meta:m,profiles:p.profiles};}
export function bridgeStructure(id){const p=profiles[id];if(!p?.bridge)return null;const group=new T.Group(),mat=new T.MeshStandardMaterial({color:'#7a807c',roughness:1}),railMat=new T.MeshStandardMaterial({color:'#9ba6a3',metalness:.4,roughness:.6});let length=0;
 function bar(a,b,width,height,material){const A=new T.Vector3(...a),B=new T.Vector3(...b),mesh=new T.Mesh(new T.BoxGeometry(width,height,A.distanceTo(B)),material);mesh.position.copy(A).add(B).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),B.sub(A).normalize());group.add(mesh);}
 for(let i=1;i<p.points.length;i++){const a=p.points[i-1],b=p.points[i],dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz);if(!len)continue;bar([a[0],a[2]-.5,a[1]],[b[0],b[2]-.5,b[1]],p.width+.3,1,mat);for(const sign of [-1,1]){const off=sign*(p.width/2+.1),ox=-dz/len*off,oz=dx/len*off;bar([a[0]+ox,a[2]+.85,a[1]+oz],[b[0]+ox,b[2]+.85,b[1]+oz],.12,.17,railMat);if(i%2===0)bar([a[0]+ox,a[2],a[1]+oz],[a[0]+ox,a[2]+.95,a[1]+oz],.12,.12,railMat);}length+=len;if(length>32){length=0;const h=a[2]-.9-heightAt(a[0],a[1]);if(h>1.5){const pier=new T.Mesh(new T.BoxGeometry(Math.min(2,p.width*.4),h,1.5),mat);pier.position.set(a[0],a[2]-.9-h/2,a[1]);group.add(pier);}}}const mergedGroup=new T.Group();for(const material of [mat,railMat]){const gs=group.children.filter(m=>m.material===material).map(m=>{m.updateMatrix();m.geometry.applyMatrix4(m.matrix);return m.geometry;});if(gs.length){const g=mergeGeometries(gs,false);if(g)mergedGroup.add(new T.Mesh(g,material));gs.forEach(g=>g.dispose());}}return mergedGroup;}
